content.text:
        links_out.append({
            "link": [e[0], e[1]],
            "round": rnd,
            "prob": [float(prob[0]), float(prob[1]), float(prob[2])],
        })

    queries_out = score_queries(queries, ixps, priors, declared, core_marginals)
    return {"version": 1, "links": links_out, "queries": queries_out}


def main():
    try:
        data = parse_request()
        answer = solve(data)
    except Invalid:
        answer = {"error": "invalid"}
    except Exception:
        # A malformed or out-of-domain request must not produce a traceback.
        answer = {"error": "invalid"}
    sys.stdout.write(json.dumps(answer, separators=(",", ":"), allow_nan=False))
    sys.stdout.write("\n")


if __name__ == "__main__":
    main()
